function Page_ActAdvanceNoticeRaceTopView:SetTimer()
    if self.TimeId then
        TimerManager:Get():StopTimer(self.TimeId)
    end
    local _beginTime, _endTime = ActAdvanceNoticeDataManager:Get():GetActTime(self.config.C_ID)
    self.TimeId = TimerManager:Get():CreateTimerLoop(1, function(class)
        if CommonHelper:GetNowTime()>_beginTime then
            local subTime=CommonHelper:SubTimeByDateTime(_endTime)
            local day,hour,minute,second=CommonHelper:GetConvertMillSecond(math.abs(subTime))
            CommonHelper:SetText("time/###time",self.gameObject, string.format("%s%s%s",CommonHelper:GetTempStr_Default(TemplateStringID.RaceOpenTimeTipsJu),CommonHelper:GetTempStr_Default(TemplateStringID.RaceTopName),CommonHelper:GetTempStr_Default(TemplateStringID.RaceEndTime,day,hour,minute,second)))
        else
            local subTime= CommonHelper:SubTimeByDateTime(_beginTime)
            local day,hour,minute,second=CommonHelper:GetConvertMillSecond(math.abs(subTime))
            CommonHelper:SetText("time/###time",self.gameObject,string.format("%s%s%s",CommonHelper:GetTempStr_Default(TemplateStringID.RaceOpenTimeTipsJu),CommonHelper:GetTempStr_Default(TemplateStringID.RaceTopName),CommonHelper:GetTempStr_Default(TemplateStringID.RaceOpenTime,day,hour,minute,second)))
        end
    end, self)
end
